<?php require_once __DIR__.'/includes/bootstrap.php';$token=(string)($_GET['token']??'');$s=$pdo->prepare('SELECT s.*,a.title FROM shares s JOIN albums a ON a.id=s.album_id WHERE s.token=? AND s.allow_download=1 AND (s.expires_at IS NULL OR s.expires_at>NOW())');$s->execute([$token]);$share=$s->fetch();if(!$share || !share_access_granted($share)){http_response_code(403);exit;}$s=$pdo->prepare('SELECT * FROM tracks WHERE album_id=? ORDER BY track_no,id');$s->execute([$share['album_id']]);$tracks=$s->fetchAll();$tmp=tempnam(sys_get_temp_dir(),'album_');$zip=new ZipArchive();if($zip->open($tmp,ZipArchive::OVERWRITE)!==true){http_response_code(500);exit('ZIP konnte nicht erstellt werden.');}foreach($tracks as $i=>$t){$file=__DIR__.'/uploads/audio/'.$t['audio_file'];if(is_file($file))$zip->addFile($file,sprintf('%02d - %s.%s',$i+1,preg_replace('/[^a-zA-Z0-9äöüÄÖÜß _.-]/u','',$t['title']),pathinfo($t['original_name'],PATHINFO_EXTENSION)));}$zip->close();$name=slugify($share['title']).'.zip';header('Content-Type: application/zip');header('Content-Disposition: attachment; filename="'.$name.'"');header('Content-Length: '.filesize($tmp));readfile($tmp);@unlink($tmp);
